+                            Iterators.single(
+                                (builder, params) -> builder.field("cluster_name", nodesStatsResponse.getClusterName().value())
+                            ),
+                            xContentChunks(nodesStatsResponse).toXContentChunked(outerParams),
+                            ChunkedToXContentHelper.endObject()
+                        ),
+                        EMPTY_PARAMS,
+                        channel
+                    )
+                );
+            }
+        });
+    }
