+        assertThat(as, transformedArrayItemsMatch(a -> a.str, arrayContaining("1", "2", "3")));
+
+        assertMismatch(
+            as,
+            transformedArrayItemsMatch(a -> a.str, arrayContainingInAnyOrder("1", "2", "4")),
+            equalTo("transformed item not matched: \"3\"")
